{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C51"],
      "claim": "KNI-272, the closest analogue (transfer 0.9653), had absolute oral bioavailability of 36.40% when given as an oral capsule post-prandially in patients, directly exceeding the 20% threshold under fed conditions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Atazanavir, a structurally related peptidomimetic HIV protease inhibitor, has oral bioavailability >90% when taken with food, supporting high F for this class in the fed state.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Paritaprevir, another peptidomimetic protease inhibitor, had absolute oral bioavailability of 52.6% from an oral tablet, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "In children, KNI-272 at 200 mg/m2 with Ora-Plus had mean absolute bioavailability of 12% (range 3.5–25%), a contradictory low-F observation for the closest analogue.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C03"],
      "claim": "Danavorexton had poor oral bioavailability requiring IV administration, a lower-transfer caution that some polar peptidomimetic-like drugs can be low.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Predicted high (F≥20%): the closest analogue KNI-272 has adult absolute oral bioavailability of ~30–55% and 36.4% post-prandially, and related peptidomimetic protease inhibitors (atazanavir, paritaprevir) show high oral F; the pediatric low-F record and poor-oral-bioavailability comparators are lower-weight or population-specific.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the exact query molecule; prediction relies on close analogue KNI-272 and related protease inhibitors.",
    "The pediatric KNI-272 record (12%) indicates possible age/formulation dependence not captured by adult fed data.",
    "The impact of the query's specific structural modifications (benzylthio, salicylamide, fused bicyclic proline) on absorption is inferred, not directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

